:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #533483;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #1f2b4d;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  width: 100%;
  max-width: 480px;
}

.game-card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: 0.5px;
}

.score-display {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.score-label {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #8899aa;
}

.score-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--snake);
  min-width: 2ch;
  text-align: right;
}

.board-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 400px;
  margin: 0 auto;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--secondary);
  border-radius: 8px;
  border: 2px solid var(--accent);
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.92);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  gap: 16px;
  backdrop-filter: blur(4px);
}

.overlay.hidden {
  display: none;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--primary);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  opacity: 0.9;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: var(--secondary);
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #d63850;
  border-color: #d63850;
}

.btn.primary:active {
  background: #b82e44;
}

.hint {
  text-align: center;
  font-size: 0.875rem;
  color: #8899aa;
  letter-spacing: 0.3px;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 80px;
    font-size: 0.9375rem;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, direction, nextDirection, food, score, running, paused, gameOver;

  function reset() {
    snake = [{x: 10, y: 10}, {x: 9, y: 10}, {x: 8, y: 10}];
    direction = {x: 1, y: 0};
    nextDirection = {x: 1, y: 0};
    score = 0;
    running = false;
    paused = true;
    gameOver = false;
    scoreEl.textContent = '0';
    spawnFood();
    draw();
  }

  function spawnFood() {
    let pos;
    do {
      pos = {x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID)};
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#1f2b4d';
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3baa87';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    direction = nextDirection;
    const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      spawnFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    running = false;
    gameOver = true;
    overlayTitle.textContent = 'Game Over';
    overlayText.innerHTML = 'Final Score: <strong>' + score + '</strong><br>Press Restart to play again.';
    startBtn.textContent = 'Play Again';
    overlay.classList.remove('hidden');
  }

  let loopId = null;

  function startLoop() {
    if (loopId) clearInterval(loopId);
    loopId = setInterval(() => {
      if (running && !paused) step();
    }, 120);
  }

  function startGame() {
    reset();
    running = true;
    paused = false;
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    startLoop();
  }

  function togglePause() {
    if (!running || gameOver) return;
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    if (paused) {
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Press Resume or Space to continue.';
      startBtn.textContent = 'Resume';
      overlay.classList.remove('hidden');
    } else {
      overlay.classList.add('hidden');
    }
  }

  function restart() {
    reset();
    overlayTitle.textContent = 'How to Play';
    overlayText.innerHTML = 'Use arrow keys to move the snake.<br>Eat the food to grow and score points.<br>Don\'t hit the walls or yourself!';
    startBtn.textContent = 'Start Game';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Pause';
    if (loopId) clearInterval(loopId);
  }

  document.addEventListener('keydown', (e) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
      e.preventDefault();
    }

    if (e.key === ' ') {
      if (!running && !gameOver) startGame();
      else togglePause();
      return;
    }

    if (!running || paused) return;

    const dirs = {
      ArrowUp: {x: 0, y: -1},
      ArrowDown: {x: 0, y: 1},
      ArrowLeft: {x: -1, y: 0},
      ArrowRight: {x: 1, y: 0}
    };

    const d = dirs[e.key];
    if (!d) return;
    if (d.x === -direction.x && d.y === -direction.y) return;
    nextDirection = d;
  });

  startBtn.addEventListener('click', () => {
    if (gameOver || (!running && paused)) {
      startGame();
    } else if (paused) {
      togglePause();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  reset();
  overlay.classList.remove('hidden');
})();
